WITH PARAMS AS ( SELECT CASE WHEN LEFT(TRIM(COALESCE(:VAR_DATA_INICIO, '')), 10) REGEXP '^[0-9]{2}/[0-9]{2}/[0-9]{4}$' THEN STR_TO_DATE(LEFT(TRIM(:VAR_DATA_INICIO), 10), '%d/%m/%Y') WHEN LEFT(TRIM(COALESCE(:VAR_DATA_INICIO, '')), 10) REGEXP '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN DATE(LEFT(TRIM(:VAR_DATA_INICIO), 10)) ELSE NULL END AS DT_INI_IN, CASE WHEN LEFT(TRIM(COALESCE(:VAR_DATA_FIM, '')), 10) REGEXP '^[0-9]{2}/[0-9]{2}/[0-9]{4}$' THEN STR_TO_DATE(LEFT(TRIM(:VAR_DATA_FIM), 10), '%d/%m/%Y') WHEN LEFT(TRIM(COALESCE(:VAR_DATA_FIM, '')), 10) REGEXP '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN DATE(LEFT(TRIM(:VAR_DATA_FIM), 10)) ELSE NULL END AS DT_FIM_IN ), D AS ( SELECT LEAST(DT_INI, DT_FIM) AS DT_INI, GREATEST(DT_INI, DT_FIM) AS DT_FIM, YEAR(GREATEST(DT_INI, DT_FIM)) AS ANO_ATU, YEAR(GREATEST(DT_INI, DT_FIM)) - 1 AS ANO_ANT, DATE_SUB(LEAST(DT_INI, DT_FIM), INTERVAL 1 YEAR) AS DT_INI_ANT, DATE_SUB(GREATEST(DT_INI, DT_FIM), INTERVAL 1 YEAR) AS DT_FIM_ANT FROM ( SELECT COALESCE(DT_FIM_IN, CURDATE()) AS DT_FIM, COALESCE(DT_INI_IN, MAKEDATE(YEAR(COALESCE(DT_FIM_IN, CURDATE())), 1)) AS DT_INI FROM PARAMS ) X ), cab AS ( SELECT MAX(C2.REFERENCIA) AS REF FROM NOTAS_EXPLICATIVAS_CAB C2 WHERE C2.CODEMP = :VAR_EMPRESA_DRE AND DATE(C2.REFERENCIA) <= (SELECT DT_FIM FROM D) ) SELECT CAB.CODEMP, CAB.REFERENCIA, T.ID, T.SOCIO, T.COTAS, T.VALOR FROM COMPOSICAO_SOCIETARIA T INNER JOIN NOTAS_EXPLICATIVAS_CAB CAB ON T.ID_NOTAS_EXPLICATIVAS_CAB = CAB.ID WHERE CAB.CODEMP = :VAR_EMPRESA_DRE AND CAB.REFERENCIA = (SELECT REF FROM cab);